(function () {
  /* data.js is generated by build.py and is not kept in the repository, so say
     plainly when it is missing rather than rendering an empty map. */
  const D = window.KH_DATA || [];
  const $ = (s) => document.querySelector(s);
  if (!window.KH_DATA) {
    const note = document.createElement('div');
    note.className = 'nodata';
    note.innerHTML = '<b>No dataset loaded.</b> Run <code>python build.py</code> to generate ' +
      '<code>docs/data.js</code> from the harmonised effect-size tables.';
    document.body.prepend(note);
  }
  const uniq = (k) => [...new Set(D.map(r => r[k]).filter(v => v !== '' && v != null))].sort();

  /* One outcome vocabulary for the filter, the heatmap columns and the tooltips:
     the indicator, plus the organism group where the source names one, so the
     abundance of weeds and of natural enemies never end up pooled in one cell. */
  const SEP = ' · ';
  D.forEach(r => {
    /* an outcome named only after its sub-pillar (Efficiency) is told apart by
       its measure instead, so the reader sees efficiency of what */
    const byMeasure = r.outcome === r.subPillar && r.subOutcome;
    r.outcomeKey = r.outcome + (r.group ? SEP + r.group : byMeasure ? SEP + r.subOutcome : '');
  });

  const DIMS = [
    { key: 'region', label: 'dimRegion' },
    { key: 'country', label: 'dimCountry' },
    { key: 'crop', label: 'dimCrop' },
    { key: 'outcomeKey', label: 'dimOutcome' },
    { key: 'practice', label: 'dimPractice' },
    { key: 'comparatorType', label: 'dimComparedWith' }
  ];
  const sel = {};
  DIMS.forEach(d => { sel[d.key] = new Set(); });
  let sort = { key: 'yi', dir: -1 };
  let selId = null;
  let map, layer, base, borders, regions, world = null, worldPending = null;
  let started = false;  /* true once the first render has run, so the theme
                           switch knows the drawing helpers are ready */

  /* ---------- language ----------
     English is what index.html already contains, so it is kept as a snapshot
     and restored rather than stored twice. t() reads the runtime strings and
     fills {name} placeholders. */
  let lang = 'en';
  const english = new Map();
  document.querySelectorAll('[data-t]').forEach(el => english.set(el, el.innerHTML));

  /* A data value as the reader should see it. Records keep their English
     values, so filtering and the CSV download are unaffected. */
  function term(value) {
    const table = (window.KH_VOCAB && window.KH_VOCAB[lang]) || {};
    return table[value] || value;
  }
  /* a composite outcome key, each half in the reader's language */
  const termKey = (value) => String(value).split(SEP).map(term).join(SEP);

  function t(key, vars) {
    const table = (window.KH_UI && window.KH_UI[lang]) || {};
    let s = key in table ? table[key] : window.KH_UI.en[key];
    if (s === undefined) return key;
    if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
    return s;
  }

  function setLang(code) {
    lang = window.KH_LANGS[code] ? code : 'en';
    const words = (window.KH_TEXT && window.KH_TEXT[lang]) || {};
    english.forEach((originalHtml, el) => {
      const key = el.dataset.t;
      el.innerHTML = key in words ? words[key] : originalHtml;
    });
    document.documentElement.lang = lang;
    $('#lang-now').textContent = window.KH_LANGS[lang];
    document.querySelectorAll('#lang-pop button').forEach(b =>
      b.classList.toggle('on', b.dataset.lang === lang));
    try { localStorage.setItem('kh-lang', lang); } catch (e) {}
    $('#theme-btn').textContent =
      document.documentElement.getAttribute('data-theme') === 'dark' ? t('themeLight') : t('themeDark');
    if (started) { buildFilters(); buildHead(); buildColPicker(); buildLegend(); buildTicks(); clearSel(); render(); }
  }

  Object.keys(window.KH_LANGS).forEach(code => {
    const b = document.createElement('button');
    b.type = 'button';
    b.dataset.lang = code;
    b.textContent = window.KH_LANGS[code];
    b.addEventListener('click', () => { $('#lang').classList.remove('open'); setLang(code); });
    $('#lang-pop').appendChild(b);
  });
  $('#lang-btn').addEventListener('click', e => {
    e.stopPropagation();
    $('#lang').classList.toggle('open');
  });
  $('#lang-pop').addEventListener('click', e => e.stopPropagation());
  document.addEventListener('click', () => $('#lang').classList.remove('open'));

  /* ---------- theme ---------- */
  const cssVar = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  function setTheme(mode) {
    document.documentElement.setAttribute('data-theme', mode);
    const b = $('#theme-btn');
    if (b) b.textContent = mode === 'dark' ? t('themeLight') : t('themeDark');
    try { localStorage.setItem('kh-theme', mode); } catch (e) {}
    if (map) redrawMap();
    if (started) paintHeroes();
  }
  let stored = null;
  try { stored = localStorage.getItem('kh-theme'); } catch (e) {}
  setTheme(stored || (window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'));
  $('#theme-btn').addEventListener('click', () =>
    setTheme(document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark'));

  /* ---------- colour scale ----------
     lnRR, symmetric and cut at ±1, which is about 0.37 to 2.7 times the
     comparator. Pink is a decrease, teal an increase. The --d tokens run teal
     to pink, so they are read in reverse here, and this is the only place
     that knows it: the points, the cells, the legend and the hero artwork all
     go through color(). */
  const BREAKS = [-1, -0.5, -0.1, 0, 0.1, 0.5, 1];
  const RAMP_VARS = ['--d7', '--d6', '--d5', '--d4', '--d3', '--d2', '--d1'];
  const ramp = () => RAMP_VARS.map(cssVar);
  const hex2 = (c) => [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)];
  const rgbOf = (v) => {
    const C = ramp(), last = BREAKS.length - 1;
    if (v === null || v === undefined || Number.isNaN(v)) return hex2(cssVar('--ink-3'));
    if (!(v > BREAKS[0])) return hex2(C[0]);
    if (v >= BREAKS[last]) return hex2(C[last]);
    for (let i = 1; i <= last; i++) {
      if (v <= BREAKS[i]) {
        const t = (v - BREAKS[i - 1]) / (BREAKS[i] - BREAKS[i - 1]);
        const A = hex2(C[i - 1]), B = hex2(C[i]);
        return A.map((x, j) => Math.round(x + (B[j] - x) * t));
      }
    }
    return hex2(C[last]);
  };
  const color = (v) => 'rgb(' + rgbOf(v).join(',') + ')';
  const inkOn = (v) => {
    const [r, g, b] = rgbOf(v);
    return (0.299 * r + 0.587 * g + 0.114 * b) > 150 ? '#15161B' : '#FFFFFF';
  };
  /* an effect size as text, and what it means as a ratio of the two means */
  const es = (v) => (v === null || v === undefined) ? '—' : (v > 0 ? '+' : '') + v.toFixed(2);
  const ratio = (v) => (v === null || v === undefined) ? '—' : '×' + Math.exp(v).toFixed(2);
  const times = (v) => (v === null || v === undefined) ? '—' : Math.exp(v).toFixed(2);   /* for prose */
  /* the word for the sign of an effect size: yi is turned so positive is better */
  const verdict = (v) => (v === null || v === undefined) ? t('legUnknown') : v > 0 ? t('legBetter') : v < 0 ? t('legWorse') : t('legSame');
  /* the median of the numbers present; null when there are none */
  const median = (a) => {
    const s = a.filter(x => x !== null && x !== undefined && !Number.isNaN(x)).sort((x, y) => x - y);
    if (!s.length) return null;
    const h = Math.floor(s.length / 2);
    return s.length % 2 ? s[h] : (s[h - 1] + s[h]) / 2;
  };
  const plural = (n, one, many) => t(n === 1 ? one : many, { n });

  /* lookups built once from the data */
  const REGION_OF = {}, SUB_OF = {}, PILLAR_OF = {};
  D.forEach(r => { REGION_OF[r.country] = r.region; SUB_OF[r.outcome] = r.subPillar; PILLAR_OF[r.subPillar] = r.pillar; });
  /* the order the heatmap groups outcomes in, by pillar then sub-pillar;
     anything the data adds later is appended at the end */
  const PILLAR_ORDER = {
    Productivity: ['Yield', 'Economics'],
    Resilience: ['Biodiversity', 'Physical', 'Efficiency', 'Social'],
    Mitigation: ['Emissions', 'Carbon Stocks', 'Cookstove'],
    Other: ['Livestock Diet']
  };
  const SUB_ORDER = Object.values(PILLAR_ORDER).flat();
  uniq('subPillar').forEach(s => { if (!SUB_ORDER.includes(s)) SUB_ORDER.push(s); });

  /* ---------- routing ---------- */
  const PAGES = ['home', 'explore', 'about', 'methodology', 'involved', 'contact'];
  function route() {
    const id = location.hash.replace('#', '') || 'home';
    const p = PAGES.includes(id) ? id : 'home';
    PAGES.forEach(k => $('#page-' + k).classList.toggle('on', k === p));
    document.querySelectorAll('#nav a').forEach(a => a.classList.toggle('on', a.hash === '#' + p));
    window.scrollTo(0, 0);
    /* the map only has a size once its page is shown, so fit it then */
    if (p === 'explore') { ensureMap(); setTimeout(() => { map.invalidateSize(); applyMapMode(); }, 80); }
  }
  window.addEventListener('hashchange', route);

  /* ---------- totals ---------- */
  $('#m-total').textContent = D.length;
  [['#h-obs', D.length], ['#h-cty', uniq('country').length], ['#h-crop', uniq('crop').length],
   ['#h-prac', uniq('practice').length], ['#h-out', uniq('outcome').length],
   ['#h-syn', uniq('synthesis').length]]
    .forEach(([s, v]) => { const el = $(s); if (el) el.textContent = v; });

  /* ---------- filter dropdowns ---------- */
  const groups = $('#filter-groups');
  function buildFilters() {
  groups.innerHTML = '';
  DIMS.forEach(d => {
    const dd = document.createElement('div');
    dd.className = 'dd';
    dd.dataset.key = d.key;
    dd.innerHTML = '<button type="button"><span class="dl-name">' + t(d.label) +
      '</span><span class="dl-val">' + t('all') + '</span><span class="car">▾</span></button>' +
      '<div class="pop"><input class="search" type="text" placeholder="' + t('search') + '">' +
      '<div class="sorts"><button type="button" data-sort="name" title="' + t('sortByName') + '"></button>' +
      '<button type="button" data-sort="count" title="' + t('sortByCount') + '"></button></div>' +
      '<div class="list"></div></div>';
    const list = dd.querySelector('.list');
    /* sort the options by name or by count; a second click on the same
       button turns the order round. Counts come first high to low. */
    dd.querySelectorAll('.sorts button').forEach(b => b.addEventListener('click', () => {
      const same = (dd.dataset.sort || 'name') === b.dataset.sort;
      dd.dataset.dir = same ? -(+dd.dataset.dir || 1) : (b.dataset.sort === 'count' ? -1 : 1);
      dd.dataset.sort = b.dataset.sort;
      sortOptions(dd);
    }));
    const byName = (a, b) => termKey(a).localeCompare(termKey(b));
    const option = (v) => {
      const l = document.createElement('label');
      l.className = 'opt';
      l.dataset.k = d.key; l.dataset.v = v;
      l.dataset.label = termKey(v);
      l.innerHTML = '<input type="checkbox"><span>' + termKey(v) + '</span><span class="c">0</span>';
      l.querySelector('input').addEventListener('change', e => {
        if (e.target.checked) sel[d.key].add(v); else sel[d.key].delete(v);
        render();
      });
      list.appendChild(l);
    };
    if (d.key === 'country') {
      /* countries sit under their UN region, the way FAOSTAT lists them */
      uniq('region').sort(byName).forEach(region => {
        const h = document.createElement('div');
        h.className = 'grp';
        h.textContent = term(region);
        list.appendChild(h);
        uniq('country').filter(c => REGION_OF[c] === region).sort(byName).forEach(option);
      });
      uniq('country').filter(c => !REGION_OF[c]).sort(byName).forEach(option);
    } else {
      uniq(d.key).sort(byName).forEach(option);
    }
    dd.querySelector('button').addEventListener('click', e => {
      e.stopPropagation();
      const was = dd.classList.contains('open');
      document.querySelectorAll('.dd.open').forEach(o => o.classList.remove('open'));
      if (!was) { dd.classList.add('open'); dd.querySelector('.search').focus(); }
    });
    dd.querySelector('.pop').addEventListener('click', e => e.stopPropagation());
    dd.querySelector('.search').addEventListener('input', e => {
      const q = e.target.value.toLowerCase();
      list.querySelectorAll('.opt').forEach(l => {
        l.style.display = l.dataset.label.toLowerCase().includes(q) ? '' : 'none';
      });
      /* a region heading with nothing left under it goes too */
      list.querySelectorAll('.grp').forEach(h => {
        let n = h.nextElementSibling, any = false;
        while (n && !n.classList.contains('grp')) { if (n.style.display !== 'none') any = true; n = n.nextElementSibling; }
        h.style.display = any ? '' : 'none';
      });
    });
    groups.appendChild(dd);
  });
  syncBoxes();
  }
  document.addEventListener('click', () => document.querySelectorAll('.dd.open').forEach(o => o.classList.remove('open')));

  /* Reorder one dropdown's options in place, so their listeners survive. The
     country list is in runs of a region heading followed by its countries;
     each run is sorted on its own and the headings stay where they are. */
  function sortOptions(dd) {
    const list = dd.querySelector('.list');
    const by = dd.dataset.sort || 'name', dir = +(dd.dataset.dir || 1);
    const count = (el) => +el.querySelector('.c').textContent;
    const cmp = (a, b) => by === 'count'
      ? (count(a) - count(b)) * dir || a.dataset.label.localeCompare(b.dataset.label)
      : a.dataset.label.localeCompare(b.dataset.label) * dir;
    const runs = [{ head: null, opts: [] }];
    [...list.children].forEach(el => {
      if (el.classList.contains('grp')) runs.push({ head: el, opts: [] });
      else runs[runs.length - 1].opts.push(el);
    });
    runs.forEach(run => {
      if (run.head) list.appendChild(run.head);
      run.opts.sort(cmp).forEach(el => list.appendChild(el));
    });
    dd.querySelectorAll('.sorts button').forEach(b => {
      const on = b.dataset.sort === by;
      b.classList.toggle('on', on);
      b.textContent = b.dataset.sort === 'name' ? (on && dir < 0 ? 'Z–A' : 'A–Z') : (on && dir > 0 ? 'n ↑' : 'n ↓');
    });
  }

  function ddLabels() {
    groups.querySelectorAll('.dd').forEach(dd => {
      const s = sel[dd.dataset.key];
      dd.classList.toggle('active', s.size > 0);
      dd.querySelector('.dl-val').textContent =
        s.size === 0 ? t('all') : s.size === 1 ? termKey([...s][0]) : t('nSelected', { n: s.size });
    });
  }
  function syncBoxes() {
    groups.querySelectorAll('.opt').forEach(l => {
      l.querySelector('input').checked = sel[l.dataset.k].has(l.dataset.v);
    });
  }
  function toggle(key, val, exclusive) {
    if (exclusive) {
      const only = sel[key].has(val) && sel[key].size === 1;
      sel[key].clear();
      if (only) { syncBoxes(); render(); return; }
    }
    if (sel[key].has(val) && !exclusive) sel[key].delete(val); else sel[key].add(val);
    /* a country picked on the map wins over a region picked in the dropdown,
       otherwise the two filters could cancel each other out to an empty map */
    if (key === 'country' && exclusive && sel.region.size && !sel.region.has(REGION_OF[val])) sel.region.clear();
    syncBoxes(); render();
  }
  $('#clear-all').addEventListener('click', () => {
    if (anyFilter()) remember();
    DIMS.forEach(d => sel[d.key].clear()); clearCols(); markFiltered(); syncBoxes(); clearSel(); render();
  });
  /* Filters set from the table headings, Excel-style: a set of values for a
     text column, a from/to range for a number column. They narrow everything,
     not only the table, so the map, the heatmap and the sentence stay in step
     with the rows. */
  const colSel = {};
  const colActive = (k) => !!colSel[k] && (colSel[k] instanceof Set ? colSel[k].size > 0 : (colSel[k].min !== null || colSel[k].max !== null));
  const asText = (v) => (v === null || v === undefined) ? '' : String(v);
  const matchOne = (r, k) => {
    const f = colSel[k];
    if (!f) return true;
    if (f instanceof Set) return f.size === 0 || f.has(asText(r[k]));
    if (f.min === null && f.max === null) return true;
    const v = r[k];
    if (v === null || v === undefined) return false;
    return (f.min === null || v >= f.min) && (f.max === null || v <= f.max);
  };
  const matchCols = (r) => Object.keys(colSel).every(k => matchOne(r, k));
  const clearCols = () => { Object.keys(colSel).forEach(k => delete colSel[k]); };
  const anyFilter = () => DIMS.some(d => sel[d.key].size) || Object.keys(colSel).some(colActive);
  const match = (r) => DIMS.every(d => sel[d.key].size === 0 || sel[d.key].has(r[d.key])) && matchCols(r);

  /* ---------- going back ----------
     A click on the heatmap or the map, Clear all and World view replace the
     selection in one go, so the view before each is kept and the Back
     button in the findings panel restores it, most recent first. */
  const past = [];
  const snapshot = () => ({
    sel: DIMS.map(d => [d.key, [...sel[d.key]]]),
    cols: Object.entries(colSel).map(([k, f]) => [k, f instanceof Set ? [...f] : { min: f.min, max: f.max }])
  });
  function remember() {
    past.push(snapshot());
    if (past.length > 20) past.shift();
    $('#back').hidden = false;
  }
  function goBack() {
    const s = past.pop();
    if (!s) return;
    s.sel.forEach(([k, values]) => { sel[k] = new Set(values); });
    clearCols();
    s.cols.forEach(([k, f]) => { colSel[k] = Array.isArray(f) ? new Set(f) : f; });
    markFiltered(); syncBoxes(); clearSel(); render();
    $('#back').hidden = past.length === 0;
  }
  $('#back').addEventListener('click', goBack);

  /* ---------- map ---------- */
  const HOME_VIEW = [[14, 12], 2];
  const ALIAS = { 'Viet Nam': 'Vietnam' };
  const wname = (c) => ALIAS[c] || c;
  /* country -> ISO3, generated as iso3.js by build.py, so the codes here
     and the files in vendor/adm1/ can never disagree */
  const ISO3 = window.KH_ISO3 || {};

  const admCache = {};
  /* Vendored by tools/fetch_boundaries.py. This used to hit geoBoundaries
     on every country click, which broke silently when they moved a file. */
  const ADM_URL = (iso) => 'vendor/adm1/' + iso + '.json';
  function loadAdm1(iso) {
    if (!iso) return Promise.resolve(null);
    if (!admCache[iso]) admCache[iso] = fetch(ADM_URL(iso)).then(r => r.ok ? r.json() : null).catch(() => null);
    return admCache[iso];
  }

  /* polygons that cross the antimeridian render as bars unless their rings are
     kept contiguous, so shift the negative side by 360 degrees */
  function fixAntimeridian(gj) {
    const fixRing = (ring) => {
      let lo = 180, hi = -180;
      ring.forEach(p => { if (p[0] < lo) lo = p[0]; if (p[0] > hi) hi = p[0]; });
      if (hi - lo <= 180) return ring;
      return ring.map(p => [p[0] < 0 ? p[0] + 360 : p[0], p[1]]);
    };
    const fixPoly = (poly) => poly.map(fixRing);
    gj.features.forEach(f => {
      const g = f.geometry;
      if (!g) return;
      if (g.type === 'Polygon') g.coordinates = fixPoly(g.coordinates);
      else if (g.type === 'MultiPolygon') g.coordinates = g.coordinates.map(fixPoly);
    });
    return gj;
  }

  function loadWorld() {
    if (world) return Promise.resolve(world);
    if (worldPending) return worldPending;
    worldPending = fetch('vendor/countries-110m.json')
      .then(r => r.json())
      .then(topo => {
        world = fixAntimeridian(topojson.feature(topo, topo.objects.countries));
        /* no field trials there, and it takes a third of the map */
        world.features = world.features.filter(f => f.properties.name !== 'Antarctica');
        return world;
      })
      .catch(err => { console.warn('Country geometry failed to load:', err); return null; });
    return worldPending;
  }

  function fitTo(bounds) {
    if (!map || !bounds || !bounds.isValid()) return;
    const size = map.getSize();
    if (!size.x || !size.y) return;   /* the page is hidden; route() fits it once shown */
    /* fill the frame: a little room at the edges, and the colour key is glass,
       so a corner under it is acceptable. maxZoom matters: a selection whose
       points all share one site has bounds with no area, and without a ceiling
       Leaflet zooms in without limit and the map goes blank. */
    map.fitBounds(bounds, { paddingTopLeft: [14, 14], paddingBottomRight: [14, 28], maxZoom: 9 });
  }
  function dataBounds(rows) {
    const pts = (rows && rows.length ? rows : D).map(r => [r.lat, r.lon]);
    return pts.length ? L.latLngBounds(pts) : null;
  }

  function ensureMap() {
    if (map) return;
    map = L.map('map', { worldCopyJump: false, minZoom: 1.5, maxZoom: 12, scrollWheelZoom: true, attributionControl: false })
      .setView(HOME_VIEW[0], HOME_VIEW[1]);
    document.getElementById('map').classList.add('plain');
    window.KH_MAP = map;
    layer = L.layerGroup().addTo(map);
    drawPoints(D.filter(match));
    drawBase();
    applyMapMode();
    fitTo(dataBounds(D.filter(match)));
    /* the map shares its row with the findings panel, so its width follows the
       window; Leaflet has to be told when that happens */
    new ResizeObserver(() => map.invalidateSize()).observe(document.getElementById('map'));
  }
  function redrawMap() {
    if (!map) return;
    if (base) { map.removeLayer(base); base = null; }
    if (borders) { map.removeLayer(borders); borders = null; }
    if (regions) { map.removeLayer(regions); regions = null; }
    drawBase();
    render();
  }

  const NAME2C = {};
  uniq('country').forEach(c => NAME2C[wname(c)] = c);
  function drawBase() {
    loadWorld().then(w => {
      if (!w || base) return;
      const on = { color: cssVar('--geo-line'), weight: .7, fillColor: cssVar('--geo-fill'), fillOpacity: 1 };
      const off = { color: cssVar('--geo-line-dim'), weight: .5, fillColor: cssVar('--geo-fill-dim'), fillOpacity: 1 };
      const styleFor = (n) => (NAME2C[n] ? on : off);
      base = L.geoJSON(w, {
        style: (f) => styleFor(f.properties && f.properties.name),
        onEachFeature: (f, l) => {
          const n = f.properties && f.properties.name;
          if (!n) return;
          const country = NAME2C[n];
          l.bindTooltip(country ? t('clickToSelect', { name: term(country) }) : n, { className: 'tip', sticky: true });
          l.on('mouseover', () => l.setStyle(country
            ? { weight: 1.2, color: cssVar('--ink-2'), fillColor: cssVar('--geo-hover') }
            : { weight: .8, color: cssVar('--geo-line') }));
          l.on('mouseout', () => l.setStyle(styleFor(n)));
          if (country) l.on('click', () => { remember(); toggle('country', country, true); });
        }
      }).addTo(map);
      base.bringToBack();
      if (layer) layer.eachLayer(m => m.bringToFront());
    });
  }
  $('#reset-view').addEventListener('click', () => {
    if (!map) return;
    if (anyFilter()) remember();
    DIMS.forEach(d => sel[d.key].clear()); clearCols(); markFiltered();
    syncBoxes(); clearSel(); render();
    map.setView(HOME_VIEW[0], HOME_VIEW[1]);
    fitTo(dataBounds(D));
  });
  function measureHead() {
    const mh = document.querySelector('.masthead');
    if (mh) document.documentElement.style.setProperty('--mh', mh.offsetHeight + 'px');
  }
  measureHead();
  window.addEventListener('resize', measureHead);

  /* ---------- hero artwork ----------
     Every comparison drawn as one cell, coloured on the same scale as the map.
     data-art names a field to band the cells by, so each page gets its own
     pattern; data-photo on the same element shows a photograph instead. */
  function paintHero(box) {
    const photo = box.dataset.photo;
    if (photo) {
      box.classList.add('photo');
      box.style.backgroundImage = 'url("' + photo + '")';
      return;
    }
    const canvas = box.querySelector('canvas');
    const w = box.clientWidth, h = box.clientHeight;
    if (!canvas || !w || !h) return;

    const groupBy = box.dataset.art;
    const byValue = (a, b) => a - b;
    let values;
    const drawn = D.filter(r => r.yi !== null);
    if (groupBy) {
      const bands = {};
      drawn.forEach(r => (bands[r[groupBy]] = bands[r[groupBy]] || []).push(r.yi));
      values = Object.values(bands).sort((a, b) => b.length - a.length)
        .flatMap(band => band.sort(byValue));
    } else {
      values = drawn.map(r => r.yi).sort(byValue);
    }
    if (!values.length) return;

    const cols = Math.max(1, Math.round(Math.sqrt(values.length * w / h)));
    const rows = Math.ceil(values.length / cols);
    /* size the cells to cover the box and let the edges crop, so the artwork
       bleeds to all four sides instead of leaving a ragged margin */
    const cell = Math.max(w / cols, h / rows);
    const left = (w - cols * cell) / 2, top = (h - rows * cell) / 2;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = w * dpr;
    canvas.height = h * dpr;
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, w, h);
    values.forEach((v, i) => {
      ctx.fillStyle = color(v);
      ctx.fillRect(left + (i % cols) * cell, top + Math.floor(i / cols) * cell,
        Math.max(1, cell - 1), Math.max(1, cell - 1));
    });
  }
  const heroes = document.querySelectorAll('.hero-art');
  const paintHeroes = () => heroes.forEach(paintHero);
  /* Redraw whenever a box changes size: on resize, when fonts settle the
     layout, and when a hidden page is shown and finally has a width. */
  const watch = new ResizeObserver(entries => entries.forEach(e => paintHero(e.target)));
  heroes.forEach(box => watch.observe(box));


  function applyMapMode() {
    if (!map) return;
    const picked = [...sel.country];
    if (borders) { map.removeLayer(borders); borders = null; }

    /* world view: every country, fitted to whatever matches the filters */
    if (!picked.length && !sel.region.size) {
      if (regions) { map.removeLayer(regions); regions = null; }
      /* Clicking a country removes this layer while the pointer is still over
         it, so its hover style never gets cleared. Reset it on the way back. */
      if (base) base.resetStyle();
      if (base && !map.hasLayer(base)) { base.addTo(map); base.bringToBack(); if (layer) layer.eachLayer(m => m.bringToFront()); }
      fitTo(dataBounds(D.filter(match)));
      return;
    }

    /* region view: the world stays, the region's countries are lifted out of it */
    if (!picked.length) {
      if (regions) { map.removeLayer(regions); regions = null; }
      if (base) { base.resetStyle(); if (!map.hasLayer(base)) { base.addTo(map); base.bringToBack(); } }
      loadWorld().then(w => {
        if (!w || sel.country.size || !sel.region.size) return;
        const inRegion = new Set(Object.keys(NAME2C).filter(n => sel.region.has(REGION_OF[NAME2C[n]])));
        const feats = w.features.filter(f => inRegion.has(f.properties.name));
        if (borders) map.removeLayer(borders);
        borders = L.geoJSON({ type: 'FeatureCollection', features: feats }, {
          style: { color: cssVar('--ink-2'), weight: 1.1, fillColor: cssVar('--geo-hover'), fillOpacity: 1 },
          interactive: false
        }).addTo(map);
        if (base) base.bringToBack();
        if (layer) layer.eachLayer(m => m.bringToFront());
        if (feats.length) fitTo(borders.getBounds());
      });
      return;
    }

    /* country view: only the chosen countries, with their regional boundaries */
    drawRegions(picked);
    loadWorld().then(w => {
      if (!w || !sel.country.size) return;
      const names = new Set([...sel.country].map(wname));
      const feats = w.features.filter(f => names.has(f.properties.name));
      if (base && map.hasLayer(base)) map.removeLayer(base);
      if (borders) map.removeLayer(borders);
      borders = L.geoJSON({ type: 'FeatureCollection', features: feats }, {
        style: { color: cssVar('--ink-2'), weight: 1.1, fillColor: cssVar('--geo-fill'), fillOpacity: 1 },
        interactive: false
      }).addTo(map);
      borders.bringToBack();
      /* with no outline for the country, the points still give the bounds */
      fitTo(feats.length ? borders.getBounds() : dataBounds(D.filter(match)));
      if (regions) regions.bringToFront();
      if (layer) layer.eachLayer(m => m.bringToFront());
    });
  }

  let regionToken = 0;
  function drawRegions(picked) {
    const token = ++regionToken;
    if (regions) { map.removeLayer(regions); regions = null; }
    const isos = picked.map(c => ISO3[c]).filter(Boolean);
    if (!isos.length) return;
    Promise.all(isos.map(loadAdm1)).then(sets => {
      if (token !== regionToken || !sel.country.size) return;
      const feats = [];
      sets.forEach(gj => { if (gj && gj.features) feats.push(...gj.features); });
      if (!feats.length) return;
      const st = { color: cssVar('--geo-region'), weight: .7, fillColor: cssVar('--geo-fill'), fillOpacity: 0 };
      regions = L.geoJSON({ type: 'FeatureCollection', features: feats }, {
        style: st,
        onEachFeature: (f, l) => {
          const n = f.properties && (f.properties.shapeName || f.properties.name);
          if (n) l.bindTooltip(n, { className: 'tip', sticky: true });
          l.on('mouseover', () => l.setStyle({ weight: 1.3, color: cssVar('--ink-2'), fillOpacity: .1, fillColor: cssVar('--accent') }));
          l.on('mouseout', () => l.setStyle(st));
        }
      }).addTo(map);
      if (borders) borders.bringToBack();
      if (layer) layer.eachLayer(m => m.bringToFront());
    });
  }

  const markers = {};
  function drawPoints(rows) {
    if (!layer) return;
    layer.clearLayers();
    for (const k in markers) delete markers[k];
    const stroke = cssVar('--panel');
    const dimmed = cssVar('--ink-3');
    rows.forEach(r => {
      const n = r.tN || 4;
      const isSel = selId === r.id;
      const other = selId && !isSel;
      const m = L.circleMarker([r.lat, r.lon], {
        radius: (3.5 + Math.min(n, 30) / 7) * (isSel ? 1.9 : 1),
        fillColor: other ? dimmed : color(r.yi),
        fillOpacity: other ? .22 : .9,
        color: isSel ? cssVar('--ink') : stroke,
        weight: isSel ? 2 : 1
      });
      m.bindTooltip(
        '<div class="tv">' + t('tipES', { es: es(r.yi), word: verdict(r.yi) }) + ', ' + termKey(r.outcomeKey) + '</div>' +
        '<div>' + t('tipVs', { practice: term(r.practice), comparator: term(r.comparator) }) + '</div>' +
        '<div class="tm">' + term(r.crop) + ', ' + term(r.country) + (r.tN ? ', ' + t('tipN', { n: r.tN }) : '') + '</div>',
        { className: 'tip', direction: 'top', offset: [0, -3] }
      );
      m.on('click', () => selectRow(r));
      m.addTo(layer);
      markers[r.id] = m;
    });
  }

  /* ---------- generated text ---------- */
  function readout(rows) {
    const texts = document.querySelectorAll('[data-readout]');
    const put = (html) => texts.forEach(n => n.innerHTML = html);
    if (!rows.length) {
      put(t('noMatch') + ' ' + t('noMatchHint'));
      return;
    }
    const filtered = anyFilter();
    /* yi is already turned so that positive means the practice did better;
       comparisons with no known direction stay out of the percentage */
    const known = rows.filter(r => r.yi !== null);
    const med = median(known.map(r => r.yi));
    const better = known.filter(r => r.yi > 0).length;
    /* where: every filter except the outcome, which gets its own clause */
    const scope = DIMS.filter(d => d.key !== 'outcomeKey' && sel[d.key].size)
      .map(d => [...sel[d.key]].slice(0, 3).map(termKey).join(', ') +
        (sel[d.key].size > 3 ? t('andMore', { n: sel[d.key].size - 3 }) : ''));
    Object.keys(colSel).filter(colActive).forEach(k => scope.push(describeCol(k)));
    /* which outcomes: the groups present, in plain words, or the outcomes picked */
    const listWords = (a) => a.length < 2 ? (a[0] || '') : a.slice(0, -1).join(', ') + ' ' + t('and') + ' ' + a[a.length - 1];
    const plain = (s) => { const k = 'group' + s.replace(/\W/g, ''); return k in window.KH_UI.en ? t(k) : term(s); };
    const subs = SUB_ORDER.filter(s => rows.some(r => r.subPillar === s));
    /* the pillars present, each with its groups: "productivity (yield, income and costs)" */
    const pillars = Object.keys(PILLAR_ORDER).filter(p => subs.some(s => PILLAR_OF[s] === p));
    subs.forEach(s => { if (!pillars.includes(PILLAR_OF[s])) pillars.push(PILLAR_OF[s]); });
    /* commas only inside the brackets: "income and costs" already has an "and" */
    const described = pillars.map(p => plain(p) + ' (' + subs.filter(s => PILLAR_OF[s] === p).map(plain).join(', ') + ')');
    const outcomes = sel.outcomeKey.size ? t('onOutcomes', { list: listWords([...sel.outcomeKey].map(termKey)) })
      : subs.length === 1 ? t('onGroup', { group: plain(subs[0]) })
      : t('acrossAll', { groups: listWords(described) });
    /* the typical difference, as a percentage the reader can picture */
    const pct = med === null ? null : Math.round((Math.exp(med) - 1) * 100);
    const diff = pct === null ? t('legUnknown') : pct > 0 ? t('betterBy', { p: pct }) : pct < 0 ? t('worseBy', { p: -pct }) : t('sameAs');
    /* what the practice was compared with: a comparison against a natural
       habitat is a different question, so the sentence says when it is one */
    const habitat = rows.filter(r => /habitat/i.test(r.comparatorType)).length;
    const vs = habitat === 0 ? t('vsFarming') : habitat === rows.length ? t('vsHabitat') : t('vsMixed', { n: habitat });
    let html = t('readout', {
      count: plural(rows.length, 'comparison', 'comparisons'), vs,
      scope: scope.length ? t('inScope', { scope: scope.join(', ') }) : '',
      outcomes, percent: known.length ? Math.round(better / known.length * 100) : '—', diff
    });
    /* which practice leads is only said once the reader has narrowed things
       down; across the whole dataset it would set unlike against unlike */
    if (filtered) {
      const byP = {};
      known.forEach(r => (byP[r.practice] = byP[r.practice] || []).push(r.yi));
      const best = Object.entries(byP).map(e => [e[0], e[1], median(e[1])])
        .filter(e => e[1].length >= 5 && e[2] !== null)
        .sort((a, b) => b[2] - a[2])[0];
      if (best) html += ' ' + t('readoutBest', { practice: term(best[0]), median: es(best[2]), n: best[1].length });
    }
    put(html);
  }

  /* ---------- practice x outcome heatmap ---------- */
  function chart(rows) {
    const box = $('#chart');
    box.innerHTML = '';
    if (!rows.length) { box.innerHTML = '<span class="lbl">' + t('nothingToSummarise') + '</span>'; return; }
    /* One column per outcome, under its sub-pillar, under its pillar: three
       header rows. The organisms behind a biodiversity outcome are pooled in
       one column, which is sound now that yi is turned so positive is better
       for weeds and natural enemies alike; the heading lists them, and the
       outcome filter can still pick one on its own. An outcome named only
       after its sub-pillar (Efficiency) is split by its measure instead. */
    const col = (r) => (r.outcome === r.subPillar && r.subOutcome) ? r.outcome + SEP + r.subOutcome : r.outcome;
    const label = (c) => c.includes(SEP) ? term(c.split(SEP)[1]) : term(c);
    const cells = {}, pCount = {}, oCount = {}, oGroups = {}, subOfCol = {};
    rows.forEach(r => {
      const c = col(r), k = r.practice + '||' + c;
      (cells[k] = cells[k] || []).push(r.yi);
      pCount[r.practice] = (pCount[r.practice] || 0) + 1;
      oCount[c] = (oCount[c] || 0) + 1;
      subOfCol[c] = r.subPillar;
      if (r.group) { const g = oGroups[c] = oGroups[c] || {}; g[r.group] = (g[r.group] || 0) + 1; }
    });
    const practices = Object.keys(pCount).sort((a, b) => pCount[b] - pCount[a]);
    /* columns sit under their sub-pillar in a fixed order, so the biodiversity
       measures are together, yield and economics together, and so on */
    const present = Object.keys(oCount);
    const subs = SUB_ORDER.filter(s => present.some(c => subOfCol[c] === s));
    present.forEach(c => { if (!subs.includes(subOfCol[c])) subs.push(subOfCol[c]); });
    const columns = subs.map(s => ({
      sub: s, pillar: PILLAR_OF[s],
      keys: present.filter(c => subOfCol[c] === s).sort((a, b) => label(a).localeCompare(label(b)))
    }));
    const outcomes = columns.flatMap(c => c.keys);
    /* the pillars, each spanning the sub-pillars under it */
    const pillars = [];
    columns.forEach(c => {
      const last = pillars[pillars.length - 1];
      if (last && last.name === c.pillar) last.span += c.keys.length; else pillars.push({ name: c.pillar, span: c.keys.length });
    });
    const organisms = (c) => oGroups[c]
      ? t('heatOf', { list: Object.entries(oGroups[c]).sort((a, b) => b[1] - a[1]).map(e => term(e[0]) + ' ' + e[1]).join(', ') })
      : '';
    /* every filter key behind a column: an outcome and its organism splits, or one measure */
    const keysOf = (c) => uniq('outcomeKey').filter(k => k === c || (!c.includes(SEP) && k.split(SEP)[0] === c));

    let html = '<div class="heat"><table><thead><tr><th class="rowh" rowspan="3"><span>' + t('heatPractice') + '</span></th>';
    pillars.forEach(p => { html += '<th class="grp pillar" colspan="' + p.span + '">' + term(p.name) + '</th>'; });
    html += '</tr><tr>';
    columns.forEach(c => {
      html += '<th class="grp" colspan="' + c.keys.length + '" title="' + t('heatGroup', { name: term(c.sub) }) + '">' + term(c.sub) + '</th>';
    });
    html += '</tr><tr>';
    outcomes.forEach(c => {
      html += '<th data-o="' + c + '" title="' + t('heatCount', { name: label(c), n: oCount[c] }) + organisms(c) + '"><span>' + label(c) + '</span></th>';
    });
    html += '</tr></thead><tbody>';
    practices.forEach(p => {
      html += '<tr><td class="rowh" data-p="' + p + '" title="' + t('heatCount', { name: term(p), n: pCount[p] }) + '">' + term(p) + '</td>';
      outcomes.forEach(o => {
        const v = cells[p + '||' + o];
        const m = v ? median(v) : null;
        if (m === null) { html += '<td class="cell empty">·</td>'; return; }
        html += '<td class="cell" data-p="' + p + '" data-o="' + o + '"' +
          ' style="background:' + color(m) + ';color:' + inkOn(m) + '"' +
          ' title="' + t('heatCell', { practice: term(p), outcome: label(o), median: es(m), ratio: times(m), n: v.length }) + '">' +
          es(m) + '<span class="cn">' + t('heatCellN', { n: v.length }) + '</span></td>';
      });
      html += '</tr>';
    });
    html += '</tbody></table></div>';
    box.innerHTML = html;

    /* a column stands for every filter key of its outcome; clicking it again lets go */
    const pickOutcome = (o) => {
      const keys = keysOf(o);
      const already = keys.length === sel.outcomeKey.size && keys.every(k => sel.outcomeKey.has(k));
      sel.outcomeKey.clear();
      if (!already) keys.forEach(k => sel.outcomeKey.add(k));
    };
    box.querySelectorAll('.cell[data-p]').forEach(td => td.addEventListener('click', () => {
      remember();
      sel.practice.clear(); sel.practice.add(td.dataset.p);
      sel.outcomeKey.clear(); keysOf(td.dataset.o).forEach(k => sel.outcomeKey.add(k));
      syncBoxes(); render();
    }));
    box.querySelectorAll('td.rowh[data-p]').forEach(td =>
      td.addEventListener('click', () => { remember(); toggle('practice', td.dataset.p, true); }));
    box.querySelectorAll('th[data-o]').forEach(th =>
      th.addEventListener('click', () => { remember(); pickOutcome(th.dataset.o); syncBoxes(); render(); }));
  }

  /* ---------- table ----------
     Every column a reader needs to understand a row without opening anything
     else. label is a key into the runtime strings; h names the one-line help
     shown on hover, which says where the number comes from. */
  const COLS = [
    { k: 'study', label: 'colStudy', h: 'helpStudy' },
    { k: 'year', label: 'colYear', h: 'helpYear', num: 1 },
    { k: 'country', label: 'dimCountry', h: 'helpCountry' },
    { k: 'lat', label: 'colLat', h: 'helpLat', num: 1 },
    { k: 'lon', label: 'colLon', h: 'helpLon', num: 1 },
    { k: 'site', label: 'colSite', h: 'helpSite' },
    { k: 'crop', label: 'dimCrop', h: 'helpCrop' },
    { k: 'pillar', label: 'colPillar', h: 'helpPillar' },
    { k: 'subPillar', label: 'colSubPillar', h: 'helpSubPillar' },
    { k: 'outcome', label: 'dimOutcome', h: 'helpOutcome' },
    { k: 'subOutcome', label: 'colSubOutcome', h: 'helpSubOutcome' },
    { k: 'group', label: 'colGroup', h: 'helpGroup' },
    { k: 'unit', label: 'colUnit', h: 'helpUnit' },
    { k: 'practice', label: 'dimPractice', h: 'helpPractice' },
    { k: 'practiceDetail', label: 'colPracticeDetail', h: 'helpPracticeDetail' },
    { k: 'comparator', label: 'colComparator', h: 'helpComparator' },
    { k: 'comparatorDetail', label: 'colComparatorDetail', h: 'helpComparatorDetail' },
    { k: 'comparatorType', label: 'colComparedWith', h: 'helpComparedWith' },
    { k: 'cMean', label: 'colCMean', h: 'helpCMean', num: 1 },
    { k: 'cSD', label: 'colCSD', h: 'helpCSD', num: 1 },
    { k: 'cN', label: 'colCN', h: 'helpCN', num: 1 },
    { k: 'tMean', label: 'colTMean', h: 'helpTMean', num: 1 },
    { k: 'tSD', label: 'colTSD', h: 'helpTSD', num: 1 },
    { k: 'tN', label: 'colTN', h: 'helpTN', num: 1 },
    { k: 'esType', label: 'colEsType', h: 'helpEsType' },
    { k: 'direction', label: 'colDirection', h: 'helpDirection' },
    { k: 'yi', label: 'colES', h: 'helpYi', num: 1 },
    { k: 'se', label: 'colSE', h: 'helpSE', num: 1 },
    { k: 'vi', label: 'colVi', h: 'helpVi', num: 1 },
    { k: 'doi', label: 'colDoi', h: 'helpDoi' }
  ];
  /* seasons and the source synthesis are in the download but not the table */
  const thr = $('#thead-row');
  const colOf = (k) => COLS.find(c => c.k === k);
  const colName = (c) => c.plain || t(c.label);

  /* which columns the reader wants to see; remembered in this browser only */
  let hiddenCols = new Set();
  try { hiddenCols = new Set(JSON.parse(localStorage.getItem('kh-hidden-cols') || '[]')); } catch (e) {}
  const shownCols = () => COLS.filter(c => !hiddenCols.has(c.k));

  function buildHead() {
    thr.innerHTML = shownCols().map(c =>
      '<th data-k="' + c.k + '" title="' + t(c.h) + '"><span class="hl">' + colName(c) + '</span><span class="ar"></span>' +
      (c.k === 'doi' ? '' : '<button type="button" class="cf" title="' + t('cfFilter') + '">▾</button>') + '</th>').join('');
    thr.querySelectorAll('th[data-k]').forEach(th => {
      th.addEventListener('click', e => {
        if (e.target.closest('.cf')) return;
        const k = th.dataset.k;
        sort = { key: k, dir: sort.key === k ? -sort.dir : (colOf(k).num ? -1 : 1) };
        render();
      });
      const cf = th.querySelector('.cf');
      if (cf) cf.addEventListener('click', e => { e.stopPropagation(); openColFilter(th.dataset.k, cf); });
    });
    markFiltered();
  }
  function markFiltered() {
    thr.querySelectorAll('th[data-k]').forEach(th => th.classList.toggle('filtered', colActive(th.dataset.k)));
  }

  /* ---------- the Columns button ---------- */
  const colDD = $('#col-dd');
  function buildColPicker() {
    const list = $('#col-list');
    list.innerHTML = '';
    COLS.forEach(c => {
      const l = document.createElement('label');
      l.className = 'opt';
      l.innerHTML = '<input type="checkbox"><span>' + colName(c) + '</span>';
      const box = l.querySelector('input');
      box.checked = !hiddenCols.has(c.k);
      box.addEventListener('change', () => {
        if (box.checked) hiddenCols.delete(c.k); else hiddenCols.add(c.k);
        rememberCols(); buildHead(); render();
      });
      list.appendChild(l);
    });
    rememberCols();
  }
  function rememberCols() {
    try { localStorage.setItem('kh-hidden-cols', JSON.stringify([...hiddenCols])); } catch (e) {}
    $('#col-val').textContent = t('colsOf', { n: COLS.length - hiddenCols.size, total: COLS.length });
  }
  colDD.querySelector('button').addEventListener('click', e => {
    e.stopPropagation();
    const was = colDD.classList.contains('open');
    document.querySelectorAll('.dd.open').forEach(o => o.classList.remove('open'));
    if (!was) colDD.classList.add('open');
  });
  colDD.querySelector('.pop').addEventListener('click', e => e.stopPropagation());
  $('#col-all').addEventListener('click', () => { hiddenCols.clear(); buildColPicker(); buildHead(); render(); });

  /* ---------- Excel-style filters on the headings ----------
     One floating panel, filled for whichever heading was clicked. Text
     columns list their values with counts; number columns take a range.
     Columns that already have a toolbar filter open that one instead. */
  const TOOLBAR_FOR = { country: 'country', crop: 'crop', practice: 'practice', comparatorType: 'comparatorType' };
  const fmtVal = (k, v) => v === '' ? t('cfEmpty')
    : WORDS.includes(k) ? term(v)
    : k === 'esType' ? (ES_SHORT[v] || v)
    : k === 'direction' ? t(+v > 0 ? 'dirUp' : +v < 0 ? 'dirDown' : 'dirUnknown')
    : v;
  const describeCol = (k) => {
    const f = colSel[k];
    const what = f instanceof Set ? [...f].slice(0, 3).map(v => fmtVal(k, v)).join(', ') + (f.size > 3 ? t('andMore', { n: f.size - 3 }) : '')
      : (f.min === null ? '…' : f.min) + '–' + (f.max === null ? '…' : f.max);
    return colName(colOf(k)).toLowerCase() + ' ' + what;
  };
  let panel = null;
  function openColFilter(k, anchor) {
    if (TOOLBAR_FOR[k]) {
      const dd = groups.querySelector('.dd[data-key="' + TOOLBAR_FOR[k] + '"]');
      if (dd) { dd.scrollIntoView({ block: 'nearest' }); dd.querySelector('button').click(); }
      return;
    }
    if (!panel) {
      panel = document.createElement('div');
      panel.className = 'colfilter';
      panel.addEventListener('click', e => e.stopPropagation());
      document.body.appendChild(panel);
      document.addEventListener('click', () => { panel.style.display = 'none'; });
      document.addEventListener('keydown', e => { if (e.key === 'Escape') panel.style.display = 'none'; });
    }
    const col = colOf(k);
    panel.innerHTML = '<div class="cf-head"><b>' + colName(col) + '</b><button type="button" class="x">✕</button></div>';
    panel.querySelector('.x').addEventListener('click', () => { panel.style.display = 'none'; });
    const done = () => { markFiltered(); render(); };

    if (col.num) {
      const f = colSel[k] || (colSel[k] = { min: null, max: null });
      panel.insertAdjacentHTML('beforeend',
        '<div class="cf-range"><label>' + t('cfFrom') + '<input type="number" step="any" class="min"></label>' +
        '<label>' + t('cfTo') + '<input type="number" step="any" class="max"></label></div>' +
        '<div class="cf-links"><button type="button" class="clear">' + t('cfClear') + '</button></div>');
      const mn = panel.querySelector('.min'), mx = panel.querySelector('.max');
      if (f.min !== null) mn.value = f.min;
      if (f.max !== null) mx.value = f.max;
      const apply = () => { f.min = mn.value === '' ? null : +mn.value; f.max = mx.value === '' ? null : +mx.value; done(); };
      mn.addEventListener('input', apply);
      mx.addEventListener('input', apply);
      panel.querySelector('.clear').addEventListener('click', () => { mn.value = ''; mx.value = ''; apply(); });
    } else {
      const f = colSel[k] || (colSel[k] = new Set());
      /* the values on offer are those left by every other filter */
      const counts = {};
      D.filter(r => DIMS.every(d => sel[d.key].size === 0 || sel[d.key].has(r[d.key])) &&
        Object.keys(colSel).every(j => j === k || matchOne(r, j)))
        .forEach(r => { const v = asText(r[k]); counts[v] = (counts[v] || 0) + 1; });
      const values = Object.keys(counts).sort((a, b) => fmtVal(k, a).localeCompare(fmtVal(k, b)));
      panel.insertAdjacentHTML('beforeend',
        '<input class="search" type="text" placeholder="' + t('search') + '">' +
        '<div class="cf-links"><button type="button" class="clear">' + t('cfClear') + '</button></div><div class="list"></div>');
      const list = panel.querySelector('.list');
      values.forEach(v => {
        const l = document.createElement('label');
        l.className = 'opt';
        l.dataset.label = fmtVal(k, v);
        l.innerHTML = '<input type="checkbox"><span>' + fmtVal(k, v) + '</span><span class="c">' + counts[v] + '</span>';
        const box = l.querySelector('input');
        box.checked = f.has(v);
        box.addEventListener('change', () => { if (box.checked) f.add(v); else f.delete(v); done(); });
        list.appendChild(l);
      });
      panel.querySelector('.search').addEventListener('input', e => {
        const q = e.target.value.toLowerCase();
        list.querySelectorAll('.opt').forEach(l => { l.style.display = l.dataset.label.toLowerCase().includes(q) ? '' : 'none'; });
      });
      panel.querySelector('.clear').addEventListener('click', () => { f.clear(); list.querySelectorAll('input').forEach(b => b.checked = false); done(); });
      setTimeout(() => panel.querySelector('.search').focus(), 0);
    }
    const r = anchor.getBoundingClientRect();
    panel.style.display = 'block';
    panel.style.left = Math.max(8, Math.min(r.left, window.innerWidth - 290)) + 'px';
    panel.style.top = (r.bottom + 4) + 'px';
  }

  /* every row is shown; the cap only returns if a dataset far larger than
     today's ever arrives, and then the footer says so */
  const MAXROWS = 5000;
  /* columns holding a controlled-vocabulary value, shown in the reader's language */
  const WORDS = ['country', 'region', 'crop', 'pillar', 'subPillar', 'outcome', 'subOutcome', 'group', 'practice', 'comparator', 'comparatorType'];
  const ES_SHORT = { 'Log Response Ratio': 'lnRR', 'Standardized Mean Difference': 'SMD' };
  const fmt = (c, r) => {
    const v = r[c.k];
    if (v === null || v === undefined || v === '') return '—';
    if (c.k === 'esType') return ES_SHORT[v] || v;
    if (c.k === 'yi') return es(v);
    if (c.k === 'se') return v.toFixed(3);
    if (c.k === 'vi') return v.toFixed(4);
    if (c.k === 'direction') return t(v > 0 ? 'dirUp' : v < 0 ? 'dirDown' : 'dirUnknown');
    if (['cMean', 'tMean', 'cSD', 'tSD'].includes(c.k)) return Number.isInteger(v) ? String(v) : v.toFixed(2);
    if (c.k === 'doi') return '<a href="https://doi.org/' + v + '" target="_blank" rel="noopener">' + v + '</a>';
    return WORDS.includes(c.k) ? term(v) : v;
  };
  function table(rows) {
    const s = [...rows].sort((a, b) => {
      let A = a[sort.key], B = b[sort.key];
      if (A === null || A === undefined) return 1;
      if (B === null || B === undefined) return -1;
      return (typeof A === 'number' ? A - B : String(A).localeCompare(String(B))) * sort.dir;
    });
    thr.querySelectorAll('th[data-k]').forEach(th => {
      th.querySelector('.ar').textContent = th.dataset.k === sort.key ? (sort.dir > 0 ? ' ↑' : ' ↓') : '';
    });
    /* the first cell carries the record's colour on its left edge; long text
       is clipped by the stylesheet, so every text cell repeats itself as a
       tooltip */
    const tip = (c, v) => (c.num || c.k === 'doi') ? '' : ' title="' + String(v).replace(/"/g, '&quot;') + '"';
    const cols = shownCols();
    $('#tbody').innerHTML = s.slice(0, MAXROWS).map(r =>
      '<tr data-id="' + r.id + '">' +
      cols.map((c, i) => { const v = fmt(c, r); return '<td class="' + (c.num ? 'v' : '') + '"' + tip(c, v) +
        (i === 0 ? ' style="--sw:' + color(r.yi) + '"' : '') + '>' + v + '</td>'; }).join('') + '</tr>'
    ).join('');
    $('#tbody').querySelectorAll('tr').forEach(tr => {
      tr.addEventListener('click', e => {
        if (e.target.closest('a')) return;   /* the DOI link is a link */
        selectRow(rows.find(r => r.id === tr.dataset.id));
      });
    });
    $('#t-note').textContent = rows.length > MAXROWS
      ? t('rowsTruncated', { shown: MAXROWS, total: rows.length })
      : t('rowsShown', { n: rows.length });
  }

  function chips() {
    document.querySelectorAll('[data-chips]').forEach(box => {
      box.innerHTML = '';
      DIMS.forEach(d => sel[d.key].forEach(v => {
        const c = document.createElement('span');
        c.className = 'chip';
        c.innerHTML = '<span>' + t(d.label) + ': ' + termKey(v) + '</span><button title="' + t('remove') + '">✕</button>';
        c.querySelector('button').addEventListener('click', () => { sel[d.key].delete(v); syncBoxes(); render(); });
        box.appendChild(c);
      }));
      /* the heading filters too: one chip per value, or one per range */
      Object.keys(colSel).filter(colActive).forEach(k => {
        const f = colSel[k], name = colName(colOf(k));
        const items = f instanceof Set ? [...f].map(v => [fmtVal(k, v), () => f.delete(v)])
          : [[(f.min === null ? '…' : f.min) + ' – ' + (f.max === null ? '…' : f.max), () => { delete colSel[k]; }]];
        items.forEach(([text, drop]) => {
          const c = document.createElement('span');
          c.className = 'chip';
          c.innerHTML = '<span>' + name + ': ' + text + '</span><button title="' + t('remove') + '">✕</button>';
          c.querySelector('button').addEventListener('click', () => { drop(); markFiltered(); render(); });
          box.appendChild(c);
        });
      });
    });
  }

  function counts() {
    groups.querySelectorAll('.opt').forEach(l => {
      const k = l.dataset.k, v = l.dataset.v;
      const n = D.filter(r => r[k] === v && matchCols(r) && DIMS.every(d => d.key === k || sel[d.key].size === 0 || sel[d.key].has(r[d.key]))).length;
      l.querySelector('.c').textContent = n;
      l.style.opacity = n === 0 ? .38 : 1;
    });
    /* the counts just changed, so a list sorted by count has to follow */
    groups.querySelectorAll('.dd').forEach(sortOptions);
  }

  /* ---------- one record picked out ----------
     From a table row or a map point: the point grows, the others dim, the row
     is marked and scrolled into view inside the table. Everything about the
     record is already in its row, so there is no separate panel. */
  function selectRow(r) {
    if (!r) return;
    selId = r.id;
    const wrap = $('.tablewrap');
    document.querySelectorAll('#tbody tr').forEach(tr => {
      const on = tr.dataset.id === r.id;
      tr.classList.toggle('sel', on);
      if (on && wrap) wrap.scrollTop = Math.max(0, tr.offsetTop - wrap.clientHeight / 2);
    });
    const badge = $('#sel-badge');
    if (badge) {
      badge.classList.add('on');
      badge.querySelector('span').textContent = t('oneHighlighted', { country: term(r.country), practice: term(r.practice) });
    }
    if (map) {
      drawPoints(D.filter(match));
      map.flyTo([r.lat, r.lon], Math.max(map.getZoom(), 8), { duration: .7 });
      if (markers[r.id]) setTimeout(() => markers[r.id] && markers[r.id].openTooltip(), 750);
    }
  }
  function clearSel() {
    if (!selId) return;
    selId = null;
    const badge = $('#sel-badge');
    if (badge) badge.classList.remove('on');
    document.querySelectorAll('#tbody tr').forEach(tr => tr.classList.remove('sel'));
    if (map) drawPoints(D.filter(match));
  }
  $('#sel-clear').addEventListener('click', clearSel);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') clearSel(); });

  /* ---------- CSV: the whole dataset, or the current selection ---------- */
  function csv(everything) {
    const rows = everything ? D : D.filter(match);
    /* the same columns, in the same order, as data.csv; build.py writes the list */
    const keys = window.KH_COLUMNS || Object.keys(rows[0] || {}).filter(k => k !== 'outcomeKey');
    const esc = (v) => v === null || v === undefined ? '' :
      /[",\n]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : v;
    const body = [keys.join(','), ...rows.map(r => keys.map(k => esc(r[k])).join(','))].join('\n');
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([body], { type: 'text/csv;charset=utf-8' }));
    a.download = 'agroecology-evidence-hub-' + (everything ? 'complete' : 'selection') + '-' + rows.length + '-comparisons.csv';
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  }
  $('#dl-all').addEventListener('click', () => csv(true));
  $('#dl-sel').addEventListener('click', () => csv(false));

  /* ---------- colour key ----------
     Built from BREAKS and RAMP_VARS, so it cannot drift from the colours the
     points and cells actually use. The swatches reference the CSS variables,
     so a theme switch recolours them with no redraw. */
  function buildLegend() {
    const swatches = $('#legend-ramp'), labels = $('#legend-lab'), ratios = $('#legend-ratio');
    if (!swatches) return;
    const tick = (v) => (v > 0 ? '+' : '') + v;
    const lo = BREAKS[0], hi = BREAKS[BREAKS.length - 1];
    swatches.innerHTML = RAMP_VARS.map(v => '<i style="background:var(' + v + ')"></i>').join('');
    labels.innerHTML = '<span>' + tick(lo) + '</span><span>0</span><span>' + tick(hi) + '</span>';
    ratios.innerHTML = '<span>' + t('legWorse') + '</span><span>' + t('legSame') + '</span><span>' + t('legBetter') + '</span>';
  }

  function render() {
    const rows = D.filter(match);
    $('#m-shown').textContent = rows.length;
    /* the selection download only makes sense once something is selected */
    const filtered = anyFilter();
    $('#dl-sel').hidden = !filtered;
    $('#dl-n').textContent = filtered ? '(' + rows.length + ')' : '';
    drawPoints(rows); readout(rows); chart(rows); table(rows); chips(); counts(); ddLabels(); applyMapMode();
  }

  /* ---------- contact form ----------
     The site is static, so there is nowhere to post to. The form opens the
     reader's mail program with the fields already filled in. Put the team's
     address here once it is agreed; until then the form says so rather than
     pretending to send. */
  const CONTACT_EMAIL = 'm.lolita@cgiar.org';
  const contactForm = $('#contact-form');
  if (contactForm) contactForm.addEventListener('submit', e => {
    e.preventDefault();
    if (!CONTACT_EMAIL) { $('#form-note').textContent = t('formNoAddress'); return; }
    const body = [...new FormData(contactForm)]
      .filter(([, v]) => v.trim())
      .map(([k, v]) => k + ': ' + v)
      .join('\n');
    location.href = 'mailto:' + CONTACT_EMAIL +
      '?subject=' + encodeURIComponent(t('formSubject')) +
      '&body=' + encodeURIComponent(body);
  });

  /* ---------- dataset submission form ----------
     The tick lists are built from the Hub's own vocabulary, so a contributor
     sees exactly the terms the data uses. Regions are a fixed world list,
     because an offer can come from anywhere, not only from what is loaded. */
  const REGIONS = [
    'Northern Africa', 'Eastern Africa', 'Middle Africa', 'Western Africa', 'Southern Africa',
    'Northern America', 'Central America', 'Caribbean', 'South America',
    'Western Asia', 'Central Asia', 'Southern Asia', 'Eastern Asia', 'South-eastern Asia',
    'Northern Europe', 'Western Europe', 'Southern Europe', 'Eastern Europe', 'Oceania'
  ];
  const submitForm = $('#submit-form');

  function buildTicks() {
    document.querySelectorAll('.chips-row[data-vocab]').forEach(box => {
      const field = box.dataset.vocab;
      const values = field === 'region' ? REGIONS : uniq(field);
      /* keep anything already picked when the labels are rebuilt in another language */
      const picked = new Set([...box.querySelectorAll('input:checked')].map(i => i.value));
      box.innerHTML = '';
      values.slice().sort((a, b) => term(a).localeCompare(term(b))).forEach(v => {
        const l = document.createElement('label');
        l.className = 'pick';
        l.innerHTML = '<input type="checkbox"><span></span>';
        const input = l.querySelector('input');
        input.name = field;
        input.value = v;            /* English, so the team reads one vocabulary */
        input.checked = picked.has(v);
        l.querySelector('span').textContent = term(v);
        box.appendChild(l);
      });
    });
  }

  if (submitForm) submitForm.addEventListener('submit', e => {
    e.preventDefault();
    if (!CONTACT_EMAIL) { $('#submit-note').textContent = t('formNoAddress'); return; }

    /* A browser cannot attach a file to a mailto, so name the chosen files in
       the message and ask the sender to attach them to the mail that opens. */
    const chosen = [...($('#submit-files') || { files: [] }).files].map(f => f.name);

    const data = new FormData(submitForm);
    const lines = [];
    new Set([...data.keys()]).forEach(key => {
      if (key === 'Files') return;
      const values = data.getAll(key).filter(v => String(v).trim());
      if (values.length) lines.push(key + ': ' + values.join(', '));
    });
    if (chosen.length) lines.push(t('submitAttachLine') + ' ' + chosen.join(', '));

    $('#submit-note').textContent = chosen.length
      ? t('submitAttach', { files: chosen.join(', ') })
      : t('submitOpened');

    location.href = 'mailto:' + CONTACT_EMAIL +
      '?subject=' + encodeURIComponent(t('submitSubject')) +
      '&body=' + encodeURIComponent(lines.join('\n\n'));
  });

  /* pick the language first, so the filters and table header are built in it */
  let savedLang = null;
  try { savedLang = localStorage.getItem('kh-lang'); } catch (e) {}
  setLang(savedLang || (navigator.language || 'en').slice(0, 2));
  buildFilters();
  buildHead();
  buildColPicker();
  buildLegend();
  buildTicks();
  started = true;
  render();
  route();
})();
